    @skip_if_dryrun
    def _start_suite(self, name, attrs):
        logger.debug(f"Starting Suite: {name}")
        self._tests = attrs["tests"]
        self._test_step = SUITE_SETUP

    @skip_if_dryrun
    def _end_suite(self, name, attrs):
        logger.debug(f"Ending Suite: {name}")
        self.stop_collecting_logs(block=True)
        self._additional_logs_executor.shutdown()
        quit_lc_servers_sequentially(logger, self.hosts)
        kill_tcp_log_server(logger)

    @skip_if_dryrun
    def _start_test(self, name, attrs):
        logger.debug(f"Starting TC: {name}")
        if self._scope != TEST_CASE:
            return
        plugins = self._get_test_plugins(["snapshot", "epc"])
        plugins = change_emil_stop_docker_inside_suite_scope(plugins, False)
        logger.debug(f"Plugins with omitted 'snapshot' and 'epc': {plugins}")
        if self._test_step == SUITE_SETUP:
            stop_plugins_names = list(plugins.keys()) + list(self._additional_plugins.keys())
            if stop_plugins_names:
                self.stop_collecting_logs(False, stop_plugins=stop_plugins_names)
            else:
                logger.debug("No plugins to stop")
        self._test_step = name
        if not self._is_blocked:
            if plugins:
                self.start_collecting_logs(plugins=plugins)
            else:
                logger.debug("No plugins to start")

    @skip_if_dryrun
    def _end_test(self, name, attrs):
        logger.debug(f"Ending TC: {name}")
        if self._scope != TEST_CASE:
            return
        if self._tests.index(name) == (len(self._tests) - 1):
            self._test_step = SUITE_TEARDOWN
        plugins = self._get_test_plugins(["snapshot", "epc"])
        stop_plugins_names = list(plugins.keys()) + list(self._additional_plugins.keys())
        if stop_plugins_names:
            self.stop_collecting_logs(False, stop_plugins=stop_plugins_names)
        else:
            logger.debug("No plugins to stop")
        if self._test_step == SUITE_TEARDOWN:
            if not self._is_blocked:
                if plugins:
                    plugins = change_emil_stop_docker_inside_suite_scope(plugins, True)
                    self.start_collecting_logs(plugins=plugins)
                else:
                    logger.debug("No plugins to start")

    @staticmethod
    def _check_new_ver():
        new_ver, latest = new_version_exists("ta_logcollector", __version__)
        if new_ver:
            logger.warning(f"New ta_logcollector version available: {__version__} -> {latest}")

    def _copy_logcollector_internal_logs(self):
        if not self._logs_destination:
            return
        for log_file in [
            path.join("/tmp", file_name) for file_name in listdir("/tmp") if file_name.endswith("logcollector.log")
        ]:
            copy(log_file, self._logs_destination)
